import * as T from 'three';
// Regrouper les détails fixes conserve la géométrie tout en réduisant les appels de dessin.
export function batchStatic(root,excluded=[]){root.updateMatrixWorld(true);const exclude=new Set(excluded),groups=new Map();root.traverse(o=>{if(!o.isMesh||o.isInstancedMesh||Array.isArray(o.material))return;let p=o;while(p){if(exclude.has(p))return;p=p.parent;}const cell=Math.floor(o.matrixWorld.elements[12]/80)+','+Math.floor(o.matrixWorld.elements[14]/80);const key=cell+o.geometry.type+JSON.stringify(o.geometry.parameters)+o.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);});for(const objects of groups.values()){if(objects.length<3)continue;const first=objects[0],inst=new T.InstancedMesh(first.geometry,first.material,objects.length);inst.castShadow=first.castShadow;inst.receiveShadow=first.receiveShadow;objects.forEach((o,i)=>{inst.setMatrixAt(i,o.matrixWorld);o.removeFromParent();if(o.geometry!==first.geometry)o.geometry.dispose();});inst.computeBoundingSphere();root.add(inst);}}
